window.C48_LEIS = window.C48_LEIS || {};
window.C48_LEIS['d70235'] = { arts: [{"n":"Início","g":"","h":"","t":"Presidência da República\nCasa Civil\nSubchefia para Assuntos Jurídicos\nDECRETO Nº 70.235, DE 6 DE MARÇO DE 1972.\nTexto compilado\nVide Lei nº 11.119, de 2005\nVide Decreto nº 6.103, de 2007.\nVide Decreto nº 7.574, de 2011\nVide Lei nº 12.715, de 2012\nVide Lei 13.140, de 2015 Dispõe sobre o processo administrativo fiscal, e dá outras providências.\nO PRESIDENTE DA REPÚBLICA, usando das atribuições que lhe confere o artigo 81, item III, da Constituição e tendo em vista o disposto no artigo 2° do Decreto-Lei n. 822, de 5 de setembro de 1969, decreta:\nDISPOSIÇÃO PRELIMINAR\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n(Incluído pela Medida Provisória nº 1.602, de 1997)"},{"n":"1º","g":"","h":"","t":"Art. 1° Este Decreto rege o processo administrativo de determinação e exigência dos créditos tributários da União e o de consulta sobre a aplicação da legislação tributária federal."},{"n":"2º","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO I - Dos Atos e Termos Processuais","t":"Art. 2º Os atos e termos processuais, quando a lei não prescrever forma determinada, conterão somente o indispensável à sua finalidade, sem espaço em branco, e sem entrelinhas, rasuras ou emendas não ressalvadas.\nParágrafo único. Os atos e termos processuais poderão ser formalizados, tramitados, comunicados e transmitidos em formato digital, conforme disciplinado em ato da administração tributária. (Redação dada pela Lei nº 12.865, de 2013)"},{"n":"3º","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO I - Dos Atos e Termos Processuais","t":"Art. 3° A autoridade local fará realizar, no prazo de trinta dias, os atos processuais que devam ser praticados em sua jurisdição, por solicitação de outra autoridade preparadora ou julgadora."},{"n":"4º","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO I - Dos Atos e Termos Processuais","t":"Art. 4º Salvo disposição em contrário, o servidor executará os atos processuais no prazo de oito dias."},{"n":"5º","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO II - Dos Prazos","t":"Art. 5º Na contagem dos prazos previstos neste Decreto: (Redação dada pela Lei Complementar nº 227, de 2026)\nI - serão considerados os dias corridos, salvo se houver disposição em contrário; e (Incluído pela Lei Complementar nº 227, de 2026)\nII - será excluído da contagem o dia do início e incluído o dia do vencimento. (Incluído pela Lei Complementar nº 227, de 2026)\nParágrafo único. Os prazos só se iniciam ou vencem no dia de expediente normal no órgão em que corra o processo ou deva ser praticado o ato."},{"n":"5º-A","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO II - Dos Prazos","t":"Art. 5º-A. Suspende-se o curso do prazo processual nos dias compreendidos entre 20 de dezembro e 20 de janeiro, inclusive. (Incluído pela Lei Complementar nº 227, de 2026)\nParágrafo único. No período referido no caput deste artigo, não serão realizadas sessões de julgamento no órgão referido no inciso II do art. 25 deste Decreto. (Incluído pela Lei Complementar nº 227, de 2026)"},{"n":"5º-B","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO II - Dos Prazos","t":"Art. 5º-B. Se não houver prazo expressamente previsto neste Decreto, será de 10 (dez) dias úteis o prazo para a realização de ato a cargo do sujeito passivo ou da Fazenda Pública. (Incluído pela Lei Complementar nº 227, de 2026)\n(Revogado pela Lei nº 8.748, de 1993)\n(Revogado pela Lei nº 8.748, de 1993)\n(Revogado pela Lei nº 8.748, de 1993)"},{"n":"7º","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 7º O procedimento fiscal tem início com: (Vide Decreto nº 3.724, de 2001)\nI - o primeiro ato de ofício, escrito, praticado por servidor competente, cientificado o sujeito passivo da obrigação tributária ou seu preposto;\nII - a apreensão de mercadorias, documentos ou livros;\nIII - o começo de despacho aduaneiro de mercadoria importada.\n§ 1° O início do procedimento exclui a espontaneidade do sujeito passivo em relação aos atos anteriores e, independentemente de intimação a dos demais envolvidos nas infrações verificadas.\n§ 2º Para os efeitos do disposto no § 1º, os atos referidos nos incisos I e II do caput deste artigo valerão pelo prazo de 90 (noventa) dias, prorrogável, sucessivamente, por igual período, com qualquer outro ato escrito que indique o prosseguimento dos trabalhos. (Redação dada pela Lei Complementar nº 227, de 2026)"},{"n":"8º","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 8º Os termos decorrentes de atividade fiscalizadora serão lavrados, sempre que possível, em livro fiscal, extraindo-se cópia para anexação ao processo; quando não lavrados em livro, entregar-se-á cópia autenticada à pessoa sob fiscalização.\n)"},{"n":"9º","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 9o A exigência do crédito tributário e a aplicação de penalidade isolada serão formalizados em autos de infração ou notificações de lançamento, distintos para cada tributo ou penalidade, os quais deverão estar instruídos com todos os termos, depoimentos, laudos e demais elementos de prova indispensáveis à comprovação do ilícito. (Redação dada pela Lei nº 11.941, de 2009)\n§ 1o Os autos de infração e as notificações de lançamento de que trata o caput deste artigo, formalizados em relação ao mesmo sujeito passivo, podem ser objeto de um único processo, quando a comprovação dos ilícitos depender dos mesmos elementos de prova. (Redação dada pela Lei nº 11.196, de 2005)\n§ 2º Os procedimentos de que tratam este artigo e o art. 7º, serão válidos, mesmo que formalizados por servidor competente de jurisdição diversa da do domicílio tributário do sujeito passivo. (Redação dada pela Lei nº 8.748, de 1993)\n§ 3º A formalização da exigência, nos termos do parágrafo anterior, previne a jurisdição e prorroga a competência da autoridade que dela primeiro conhecer. (Incluído pela Lei nº 8.748, de 1993)\n§ 4o O disposto no caput deste artigo aplica-se também nas hipóteses em que, constatada infração à legislação tributária, dela não resulte exigência de crédito tributário. (Incluído pela Lei nº 11.941, de 2009)\n§ 5o Os autos de infração e as notificações de lançamento de que trata o caput deste artigo, formalizados em decorrência de fiscalização relacionada a regime especial unificado de arrecadação de tributos, poderão conter lançamento único para todos os tributos por eles abrangidos. (Incluído pela Lei nº 11.941, de 2009)\n§ 6o O disposto no caput não se aplica às contribuições de que trata o art. 3o da Lei no 11.457, de 16 de março de 2007. (Incluído pela Medida Provisória nº 449, de 2008)\n§ 6o O disposto no caput deste artigo não se aplica às contribuições de que trata o art. 3º da Lei nº 11.457, de 16 de março de 2007. (Incluído pela Lei nº 11.941, de 2009)\n§ 7o O Poder Executivo poderá estabelecer outras situações nas quais um único lançamento abrangerá mais de um tributo. (Vide Medida Provisória nº 449, de 2008)"},{"n":"10","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 10. O auto de infração será lavrado por servidor competente, no local da verificação da falta, e conterá obrigatoriamente:\nI - a qualificação do autuado;\nII - o local, a data e a hora da lavratura;\nIII - a descrição do fato;\nIV - a disposição legal infringida e a penalidade aplicável;\nV - a determinação da exigência e a intimação para cumpri-la ou impugná-la no prazo de 20 (vinte) dias úteis; (Redação dada pela Lei Complementar nº 227, de 2026)\nVI - a assinatura do autuante e a indicação de seu cargo ou função e o número de matrícula."},{"n":"11","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 11. A notificação de lançamento será expedida pelo órgão que administra o tributo e conterá obrigatoriamente:\nI - a qualificação do notificado;\nII - o valor do crédito tributário e o prazo para recolhimento ou impugnação;\nIII - a disposição legal infringida, se for o caso;\nIV - a assinatura do chefe do órgão expedidor ou de outro servidor autorizado e a indicação de seu cargo ou função e o número de matrícula.\nParágrafo único. Prescinde de assinatura a notificação de lançamento emitida por processo eletrônico."},{"n":"12","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 12. O servidor que verificar a ocorrência de infração à legislação tributária federal e não for competente para formalizar a exigência, comunicará o fato, em representação circunstanciada, a seu chefe imediato, que adotará as providências necessárias."},{"n":"13","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 13. A autoridade preparadora determinará que seja informado, no processo, se o infrator é reincidente, conforme definição da lei específica, se essa circunstância não tiver sido declarada na formalização da exigência."},{"n":"14","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 14. A impugnação da exigência instaura a fase litigiosa do procedimento."},{"n":"14-A","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 14-A. Art. 14-A. No caso de determinação e exigência de créditos tributários da União cujo sujeito passivo seja órgão ou entidade de direito público da administração pública federal, a submissão do litígio à composição extrajudicial pela Advocacia-Geral da União é considerada reclamação, para fins do disposto no inciso III do art. 151 da Lei no 5.172, de 25 de outubro de 1966 - Código Tributário Nacional. (Incluído pela Lei nº 13.140, de 2015) Vigência"},{"n":"15","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 15. A impugnação, formalizada por escrito e instruída com os documentos em que se fundamentar, será apresentada ao órgão preparador no prazo de 20 (vinte) dias úteis, contado da data em que for feita a intimação da exigência. (Redação dada pela Lei Complementar nº 227, de 2026)\n(Revogado pela Lei nº 11.941, de 2009)"},{"n":"16","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 16. A impugnação mencionará:\nI - a autoridade julgadora a quem é dirigida;\nII - a qualificação do impugnante;\nIII - os motivos de fato e de direito em que se fundamenta, os pontos de discordância e as razões e provas que possuir; (Redação dada pela Lei nº 8.748, de 1993)\nIV - as diligências, ou perícias que o impugnante pretenda sejam efetuadas, expostos os motivos que as justifiquem, com a formulação dos quesitos referentes aos exames desejados, assim como, no caso de perícia, o nome, o endereço e a qualificação profissional do seu perito. (Redação dada pela Lei nº 8.748, de 1993)\nV - se a matéria impugnada foi submetida à apreciação judicial, devendo ser juntada cópia da petição. (Incluído pela Lei nº 11.196, de 2005)\n§ 1º Considerar-se-á não formulado o pedido de diligência ou perícia que deixar de atender aos requisitos previstos no inciso IV do art. 16. (Redação dada pela Lei nº 8.748, de 1993)\n§ 2º É defeso ao impugnante, ou a seu representante legal, empregar expressões injuriosas nos escritos apresentados no processo, cabendo ao julgador, de ofício ou a requerimento do ofendido, mandar riscá-las. (Redação dada pela Lei nº 8.748, de 1993)\n§ 3º Quando o impugnante alegar direito municipal, estadual ou estrangeiro, provar-lhe-á o teor e a vigência, se assim o determinar o julgador. (Incluído pela Lei nº 8.748, de 1993)\n§ 4º A prova documental será apresentada na impugnação, precluindo o direito de o impugnante fazê-lo em outro momento processual, a menos que: (Incluído pela Medida Provisória nº 1.602, de 1997)\na) fique demonstrada a impossibilidade de sua apresentação oportuna, por motivo de força maior; (Incluído pela Medida Provisória nº 1.602, de 1997)\nb) refira-se a fato ou a direito superveniente; (Incluído pela Medida Provisória nº 1.602, de 1997)\nc) destine-se a contrapor fatos ou razões posteriormente trazidas aos autos. (Incluído pela Medida Provisória nº 1.602, de 1997)\n§ 4º A prova documental será apresentada na impugnação, precluindo o direito de o impugnante fazê-lo em outro momento processual, a menos que: (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\na) fique demonstrada a impossibilidade de sua apresentação oportuna, por motivo de força maior; (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\nb) refira-se a fato ou a direito superveniente; (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\nc) destine-se a contrapor fatos ou razões posteriormente trazidas aos autos. (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n§ 5º A juntada de documentos após a impugnação deverá ser requerida à autoridade julgadora, mediante petição em que se demonstre, com fundamentos, a ocorrência de uma das condições previstas nas alíneas do parágrafo anterior. (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n§ 6º Caso já tenha sido proferida a decisão, os documentos apresentados permanecerão nos autos para, se for interposto recurso, serem apreciados pela autoridade julgadora de segunda instância. (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\n(Redação dada pela Medida Provisória nº 1.602, de 1997)"},{"n":"17","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 17. Considerar-se-á não impugnada a matéria que não tenha sido expressamente contestada pelo impugnante. (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)"},{"n":"18","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 18. A autoridade julgadora de primeira instância determinará, de ofício ou a requerimento do impugnante, a realização de diligências ou perícias, quando entendê-las necessárias, indeferindo as que considerar prescindíveis ou impraticáveis, observando o disposto no art. 28, in fine. (Redação dada pela Lei nº 8.748, de 1993)\n§ 1º Deferido o pedido de perícia, ou determinada de ofício, sua realização, a autoridade designará servidor para, como perito da União, a ela proceder e intimará o perito do sujeito passivo a realizar o exame requerido, cabendo a ambos apresentar os respectivos laudos em prazo que será fixado segundo o grau de complexidade dos trabalhos a serem executados.(Redação dada pela Lei nº 8.748, de 1993)\n§ 2º Os prazos para realização de diligência ou perícia poderão ser prorrogados, a juízo da autoridade. (Redação dada pela Lei nº 8.748, de 1993)\n§ 3º Quando, em exames posteriores, diligências ou perícias, realizados no curso do processo, forem verificadas incorreções, omissões ou inexatidões de que resultem agravamento da exigência inicial, inovação ou alteração da fundamentação legal da exigência, será lavrado auto de infração ou emitida notificação de lançamento complementar, devolvendo-se, ao sujeito passivo, prazo para impugnação no concernente à matéria modificada. (Redação dada pela Lei nº 8.748, de 1993)\n(Revogado pela Lei nº 8.748, de 1993)"},{"n":"20","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 20. No âmbito da Secretaria da Receita Federal, a designação de servidor para proceder aos exames relativos a diligências ou perícias recairá sobre Auditor-Fiscal do Tesouro Nacional. (Redação dada pela Lei nº 8.748, de 1993)"},{"n":"21","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 21. Não sendo cumprida nem impugnada a exigência, a autoridade preparadora declarará a revelia, permanecendo o processo no órgão preparador, pelo prazo de trinta dias, para cobrança amigável. (Redação dada pela Lei nº 8.748, de 1993)\n§ 1º No caso de impugnação parcial, não cumprida a exigência relativa à parte não litigiosa do crédito, o órgão preparador, antes da remessa dos autos a julgamento, providenciará a formação de autos apartados para a imediata cobrança da parte não contestada, consignando essa circunstância no processo original. (Redação dada pela Lei nº 8.748, de 1993)\n§ 2º A autoridade preparadora, após a declaração de revelia e findo o prazo previsto no caput deste artigo, procederá, em relação às mercadorias e outros bens perdidos em razão de exigência não impugnada, na forma do art. 63. (Redação dada pela Lei nº 8.748, de 1993)\n§ 3° Esgotado o prazo de cobrança amigável sem que tenha sido pago o crédito tributário, o órgão preparador declarará o sujeito passivo devedor remisso e encaminhará o processo à autoridade competente para promover a cobrança executiva.\n§ 4º O disposto no parágrafo anterior aplicar-se-á aos casos em que o sujeito passivo não cumprir as condições estabelecidas para a concessão de moratória.\n(Vide Lei nº 8.748, de 1993)"},{"n":"22","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO III - Do Procedimento","t":"Art. 22. O processo será organizado em ordem cronológica e terá suas folhas numeradas e rubricadas."},{"n":"23","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO IV - Da Intimação","t":"Art. 23. Far-se-á a intimação:\n(Redação dada pela Medida Provisória nº 1.602, de 1997)\nI - pessoal, pelo autor do procedimento ou por agente do órgão preparador, na repartição ou fora dela, provada com a assinatura do sujeito passivo, seu mandatário ou preposto, ou, no caso de recusa, com declaração escrita de quem o intimar; (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\n(Redação dada pela Medida Provisória nº 1.602, de 1997)\nII - por via postal, telegráfica ou por qualquer outro meio ou via, com prova de recebimento no domicílio tributário eleito pelo sujeito passivo; (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\nIII - por meio eletrônico, com prova de recebimento, mediante: (Redação dada pela Lei nº 11.196, de 2005)\na) envio ao domicílio tributário do sujeito passivo; ou (Incluída pela Lei nº 11.196, de 2005)\nb) registro em meio magnético ou equivalente utilizado pelo sujeito passivo. (Incluída pela Lei nº 11.196, de 2005)\n§ 1o Quando resultar improfícuo um dos meios previstos no caput deste artigo ou quando o sujeito passivo tiver sua inscrição declarada inapta perante o cadastro fiscal, a intimação poderá ser feita por edital publicado: (Redação dada pela Lei nº 11.941, de 2009)\nI - no endereço da administração tributária na internet; (Incluído pela Lei nº 11.196, de 2005)\nII - em dependência, franqueada ao público, do órgão encarregado da intimação; ou (Incluído pela Lei nº 11.196, de 2005)\nIII - uma única vez, em órgão da imprensa oficial local. (Incluído pela Lei nº 11.196, de 2005)\n§ 2° Considera-se feita a intimação:\nI - na data da ciência do intimado ou da declaração de quem fizer a intimação, se pessoal;\n(Redação dada pela Medida Provisória nº 1.602, de 1997)\nII - no caso do inciso II do caput deste artigo, na data do recebimento ou, se omitida, quinze dias após a data da expedição da intimação; (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\n(Redação dada pela Medida Provisória nº 1.602, de 1997)\na) quinze dias contados da data registrada no comprovante de entrega no domicílio tributário do sujeito passivo; (Redação dada pela Medida Provisória nº 449, de 2008)\nb) na data em que o sujeito passivo efetuar consulta no endereço eletrônico a ele atribuído pela administração tributária, se ocorrida antes do prazo previsto na alínea “a”; ou (Redação dada pela Medida Provisória nº 449, de 2008)\nc) na data registrada no meio magnético ou equivalente utilizado pelo sujeito passivo; (Incluído pela Medida Provisória nº 449, de 2008)\n(Vide Medida Provisória nº 449, de 2008)\n(Vide Medida Provisória nº 449, de 2008)\n(Vide Medida Provisória nº 449, de 2008)\nIII - se por meio eletrônico: (Redação dada pela Lei nº 12.844, de 2013)\na) 15 (quinze) dias contados da data registrada no comprovante de entrega no domicílio tributário do sujeito passivo; (Redação dada pela Lei nº 12.844, de 2013)\nb) na data em que o sujeito passivo efetuar consulta no endereço eletrônico a ele atribuído pela administração tributária, se ocorrida antes do prazo previsto na alínea a; ou (Redação dada pela Lei nº 12.844, de 2013)\nc) na data registrada no meio magnético ou equivalente utilizado pelo sujeito passivo; (Incluída pela Lei nº 12.844, de 2013)\nIV - 15 (quinze) dias após a publicação do edital, se este for o meio utilizado. (Incluído pela Lei nº 11.196, de 2005)\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n§ 3o Os meios de intimação previstos nos incisos do caput deste artigo não estão sujeitos a ordem de preferência. (Redação dada pela Lei nº 11.196, de 2005)\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n§ 4o Para fins de intimação, considera-se domicílio tributário do sujeito passivo: (Redação dada pela Lei nº 11.196, de 2005)\nI - o endereço postal por ele fornecido, para fins cadastrais, à administração tributária; e (Incluído pela Lei nº 11.196, de 2005)\nII - o endereço eletrônico a ele atribuído pela administração tributária, desde que autorizado pelo sujeito passivo. (Incluído pela Lei nº 11.196, de 2005)\n§ 5o O endereço eletrônico de que trata este artigo somente será implementado com expresso consentimento do sujeito passivo, e a administração tributária informar-lhe-á as normas e condições de sua utilização e manutenção. (Incluído pela Lei nº 11.196, de 2005)\n§ 6o As alterações efetuadas por este artigo serão disciplinadas em ato da administração tributária. (Incluído pela Lei nº 11.196, de 2005)\n§ 7o Os Procuradores da Fazenda Nacional serão intimados pessoalmente das decisões do Conselho de Contribuintes e da Câmara Superior de Recursos Fiscais, do Ministério da Fazenda na sessão das respectivas câmaras subseqüente à formalização do acórdão.(Incluído pela Lei nº 11.457, de 2007) (Vigência)\n§ 8o Se os Procuradores da Fazenda Nacional não tiverem sido intimados pessoalmente em até 40 (quarenta) dias contados da formalização do acórdão do Conselho de Contribuintes ou da Câmara Superior de Recursos Fiscais, do Ministério da Fazenda, os respectivos autos serão remetidos e entregues, mediante protocolo, à Procuradoria da Fazenda Nacional, para fins de intimação.(Incluído pela Lei nº 11.457, de 2007) (Vigência)\n§ 9o Os Procuradores da Fazenda Nacional serão considerados intimados pessoalmente das decisões do Conselho de Contribuintes e da Câmara Superior de Recursos Fiscais, do Ministério da Fazenda, com o término do prazo de 30 (trinta) dias contados da data em que os respectivos autos forem entregues à Procuradoria na forma do § 8o deste artigo. (Incluído pela Lei nº 11.457, de 2007) (Vigência)"},{"n":"24","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO V - Da Competência","t":"Art. 24. O preparo do processo compete à autoridade local do órgão encarregado da administração do tributo.\nParágrafo único. Quando o ato for praticado por meio eletrônico, a administração tributária poderá atribuir o preparo do processo a unidade da administração tributária diversa da prevista no caput deste artigo. (Redação dada pela Lei nº 11.941, de 2009)"},{"n":"25","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO V - Da Competência","t":"Art. 25. O julgamento do processo de exigência de tributos ou contribuições administrados pela Secretaria da Receita Federal compete: (Vide Decreto nº 2.562, de 1998) (Redação dada pela Medida Provisória nº 2.158-35, de 2001)\nI - em primeira instância, às Delegacias da Receita Federal de Julgamento, órgãos de deliberação interna e natureza colegiada da Secretaria da Receita Federal; (Redação dada pela Medida Provisória nº 2.158-35, de 2001)\nI - em primeira instância, às Delegacias da Receita Federal de Julgamento, órgãos de deliberação interna e natureza colegiada da Secretaria da Receita Federal; (Redação dada pela Medida Provisória nº 2.158-35, de 2001) (Vide Lei nº 8.748, de 1993)\na) aos Delegados da Receita Federal, titulares de Delegacias especializadas nas atividades concernentes a julgamento de processos, quanto aos tributos e contribuições administrados pela Secretaria da Receita Federal. (Redação dada pela Lei nº 8.748, de 1993)\na) aos Delegados da Receita Federal, titulares de Delegacias especializadas nas atividades concernentes a julgamento de processos, quanto aos tributos e contribuições administrados pela Secretaria da Receita Federal. (Redação dada pela Lei nº 8.748, de 1993) (Vide Medida Provisória nº 232, de 2004) (Vide Lei nº 11.119, de 2005)\nb) às autoridades mencionadas na legislação de cada um dos demais tributos ou, na falta dessa indicação aos chefes da projeção regional ou local da entidade que administra o tributo, conforme for por ela estabelecido.\nb) às autoridades mencionadas na legislação de cada um dos demais tributos ou, na falta dessa indicação aos chefes da projeção regional ou local da entidade que administra o tributo, conforme for por ela estabelecido.\nII – em segunda instância, ao Conselho Administrativo de Recursos Fiscais, órgão colegiado, paritário, integrante da estrutura do Ministério da Fazenda, com atribuição de julgar recursos de ofício e voluntários de decisão de primeira instância, bem como recursos de natureza especial. (Redação dada pela Lei nº 11.941, de 2009)\n§ 1o O Conselho Administrativo de Recursos Fiscais será constituído por seções e pela Câmara Superior de Recursos Fiscais. (Redação dada pela Medida Provisória nº 449, de 2008)\n§ 1o O Conselho Administrativo de Recursos Fiscais será constituído por seções e pela Câmara Superior de Recursos Fiscais. (Redação dada pela Lei nº 11.941, de 2009)\nI – (revogado); (Redação dada pela Lei nº 11.941, de 2009)\nII – (revogado); (Redação dada pela Lei nº 11.941, de 2009)\nIII – (revogado); (Redação dada pela Lei nº 11.941, de 2009)\nIV – (revogado). (Redação dada pela Lei nº 11.941, de 2009)\n§ 2o As seções serão especializadas por matéria e constituídas por câmaras. (Redação dada pela Medida Provisória nº 449, de 2008)\n§ 2o As seções serão especializadas por matéria e constituídas por câmaras. (Redação dada pela Lei nº 11.941, de 2009)\n§ 3o A Câmara Superior de Recursos Fiscais será constituída por turmas, compostas pelos Presidentes e Vice-Presidentes das câmaras. (Redação dada pela Medida Provisória nº 449, de 2008)\n§ 3o A Câmara Superior de Recursos Fiscais será constituída por turmas, compostas pelos Presidentes e Vice-Presidentes das câmaras. (Redação dada pela Lei nº 11.941, de 2009)\n§ 4o As câmaras poderão ser divididas em turmas. (Redação dada pela Medida Provisória nº 449, de 2008)\n§ 4o As câmaras poderão ser divididas em turmas. (Redação dada pela Lei nº 11.941, de 2009)\n§ 5o O Ministro de Estado da Fazenda poderá criar, nas seções, turmas especiais, de caráter temporário, com competência para julgamento de processos que envolvam valores reduzidos ou matéria recorrente ou de baixa complexidade, que poderão funcionar nas cidades onde estão localizadas as Superintendências Regionais da Receita Federal do Brasil. (Redação dada pela Medida Provisória nº 449, de 2008)\n§ 5o O Ministro de Estado da Fazenda poderá criar, nas seções, turmas especiais, de caráter temporário, com competência para julgamento de processos que envolvam valores reduzidos, que poderão funcionar nas cidades onde estão localizadas as Superintendências Regionais da Receita Federal do Brasil. (Redação dada pela Lei nº 11.941, de 2009)\n§ 6o Na composição das câmaras, das suas turmas e das turmas especiais, será respeitada a paridade entre representantes da Fazenda Nacional e representantes dos contribuintes. (Incluído pela Medida Provisória nº 449, de 2008)\n§ 6o (VETADO) (Incluído pela Lei nº 11.941, de 2009)\n§ 7o As turmas da Câmara Superior de Recursos Fiscais serão constituídas pelo Presidente do Conselho Administrativo de Recursos Fiscais, pelo Vice-Presidente, pelos Presidentes e pelos Vice-Presidentes das câmaras. (Incluído pela Medida Provisória nº 449, de 2008)\n§ 7o As turmas da Câmara Superior de Recursos Fiscais serão constituídas pelo Presidente do Conselho Administrativo de Recursos Fiscais, pelo Vice-Presidente, pelos Presidentes e pelos Vice-Presidentes das câmaras, respeitada a paridade. (Incluído pela Lei nº 11.941, de 2009)\n§ 8o A presidência das turmas da Câmara Superior de Recursos Fiscais será exercida pelo Presidente do Conselho Administrativo de Recursos Fiscais e a vice-presidência, por conselheiro representante dos contribuintes. (Incluído pela Medida Provisória nº 449, de 2008)\n§ 8o A presidência das turmas da Câmara Superior de Recursos Fiscais será exercida pelo Presidente do Conselho Administrativo de Recursos Fiscais e a vice-presidência, por conselheiro representante dos contribuintes. (Incluído pela Lei nº 11.941, de 2009)\n§ 9o Os cargos de Presidente das Turmas da Câmara Superior de Recursos Fiscais, das câmaras, das suas turmas e das turmas especiais serão ocupados por conselheiros representantes da Fazenda Nacional, que, em caso de empate, terão o voto de qualidade, e os cargos de Vice-Presidente, por representantes dos contribuintes. (Incluído pela Medida Provisória nº 449, de 2008)\n§ 9o Os cargos de Presidente das Turmas da Câmara Superior de Recursos Fiscais, das câmaras, das suas turmas e das turmas especiais serão ocupados por conselheiros representantes da Fazenda Nacional, que, em caso de empate, terão o voto de qualidade, e os cargos de Vice-Presidente, por representantes dos contribuintes. (Incluído pela Lei nº 11.941, de 2009)\n§ 9º-A. Ficam excluídas as multas e cancelada a representação fiscal para os fins penais de que trata o art. 83 da Lei nº 9.430, de 27 de dezembro de 1996, na hipótese de julgamento de processo administrativo fiscal resolvido favoravelmente à Fazenda Pública pelo voto de qualidade previsto no § 9º deste artigo. (Incluído pela Lei nº 14.689, de 2023)\n§ 10. Os conselheiros serão designados pelo Ministro de Estado da Fazenda para mandato, limitando-se as reconduções, na forma e no prazo estabelecidos no regimento interno. (Incluído pela Medida Provisória nº 449, de 2008)\n§ 10. Os conselheiros serão designados pelo Ministro de Estado da Fazenda para mandato, limitando-se as reconduções, na forma e no prazo estabelecidos no regimento interno. (Incluído pela Lei nº 11.941, de 2009)\n§ 11. O Ministro de Estado da Fazenda, observado o devido processo legal, decidirá sobre a perda do mandato dos conselheiros que incorrerem em falta grave, definida no regimento interno. (Incluído pela Lei nº 11.941, de 2009)\n§ 12. Nos julgamentos realizados pelos órgãos colegiados referidos nos incisos I e II do caput deste artigo, é assegurada ao procurador do sujeito passivo a realização de sustentação oral, na forma do regulamento. (Incluído pela Lei nº 14.689, de 2023)\n§ 13. Os órgãos julgadores referidos nos incisos I e II do caput deste artigo observarão as súmulas de jurisprudência publicadas pelo Conselho Administrativo de Recursos Fiscais. (Incluído pela Lei nº 14.689, de 2023)"},{"n":"25-A","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO V - Da Competência","t":"Art. 25-A. Na hipótese de julgamento de processo administrativo fiscal resolvido definitivamente a favor da Fazenda Pública pelo voto de qualidade previsto no § 9º do art. 25 deste Decreto, e desde que haja a efetiva manifestação do contribuinte para pagamento no prazo de 90 (noventa) dias, serão excluídos, até a data do acordo para pagamento, os juros de mora de que trata o art. 13 da Lei nº 9.065, de 20 de junho de 1995. (Incluído pela Lei nº 14.689, de 2023)\n§ 1º O pagamento referido no caput deste artigo poderá ser realizado em até 12 (doze) parcelas, mensais e sucessivas, corrigidas nos termos do art. 13 da Lei nº 9.065, de 20 de junho de 1995, e abrangerá o montante principal do crédito tributário. (Incluído pela Lei nº 14.689, de 2023)\n§ 2º No caso de não pagamento nos termos do caput ou de inadimplemento de qualquer das parcelas previstas no § 1º deste artigo, serão retomados os juros de mora de que trata o art. 13 da Lei nº 9.065, de 20 de junho de 1995. (Incluído pela Lei nº 14.689, de 2023)\n§ 3º Para efeito do disposto no § 1º deste artigo, admite-se a utilização de créditos de prejuízo fiscal e de base de cálculo negativa da Contribuição Social sobre o Lucro Líquido (CSLL) de titularidade do sujeito passivo, de pessoa jurídica controladora ou controlada, de forma direta ou indireta, ou de sociedades que sejam controladas direta ou indiretamente por uma mesma pessoa jurídica, apurados e declarados à Secretaria Especial da Receita Federal do Brasil, independentemente do ramo de atividade. (Incluído pela Lei nº 14.689, de 2023)\n§ 4º O valor dos créditos a que se refere o § 3º deste artigo será determinado, na forma da regulamentação: (Incluído pela Lei nº 14.689, de 2023)\nI – por meio da aplicação das alíquotas do imposto de renda previstas no art. 3º da Lei nº 9.249, de 26 de dezembro de 1995, sobre o montante do prejuízo fiscal; e\nII – por meio da aplicação das alíquotas da CSLL previstas no art. 3º da Lei nº 7.689, de 15 de dezembro de 1988, sobre o montante da base de cálculo negativa da contribuição.\n§ 5º A utilização dos créditos a que se refere o § 3º deste artigo extingue os débitos sob condição resolutória de sua ulterior homologação. (Incluído pela Lei nº 14.689, de 2023)\n§ 6º A Secretaria Especial da Receita Federal do Brasil dispõe do prazo de 5 (cinco) anos para a análise dos créditos utilizados na forma do § 3º deste artigo. (Incluído pela Lei nº 14.689, de 2023)\n§ 7º O disposto no caput deste artigo aplica-se exclusivamente à parcela controvertida, resolvida pelo voto de qualidade previsto no § 9º do art. 25 deste Decreto, no âmbito do Conselho Administrativo de Recursos Fiscais. (Incluído pela Lei nº 14.689, de 2023)\n§ 8º Se não houver opção pelo pagamento na forma deste artigo, os créditos definitivamente constituídos serão encaminhados para inscrição em dívida ativa da União em até 90 (noventa) dias e: (Incluído pela Lei nº 14.689, de 2023)\nI – não incidirá o encargo de que trata o art. 1º do Decreto-Lei nº 1.025, de 21 de outubro de 1969; e\nII – será aplicado o disposto no § 9º-A do art. 25 deste Decreto.\n§ 9º No curso do prazo previsto no caput deste artigo, os créditos tributários objeto de negociação não serão óbice à emissão de certidão de regularidade fiscal, nos termos do art. 206 da Lei nº 5.172, de 25 de outubro de 1966 (Código Tributário Nacional). (Incluído pela Lei nº 14.689, de 2023)\n§ 10. O pagamento referido no § 1º deste artigo compreende o uso de precatórios para amortização ou liquidação do remanescente, na forma do § 11 do art. 100 da Constituição Federal. (Incluído pela Lei nº 14.689, de 2023)\nParágrafo único. A Câmara Superior de Recursos Fiscais poderá rever ou cancelar súmula, de ofício ou mediante proposta apresentada pelo Procurador-Geral da Fazenda Nacional ou pelo Secretário da Receita Federal do Brasil. (Incluído pela Medida Provisória nº 449, de 2008)"},{"n":"26","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO V - Da Competência","t":"Art. 26. Compete ao Ministro da Fazenda, em instância especial: (Vide Medida Provisória nº 449, de 2008)\nI - julgar recursos de decisões dos Conselhos de Contribuintes, interpostos pelos Procuradores Representantes da Fazenda junto aos mesmos Conselhos; (Vide Medida Provisória nº 449, de 2008)\nII - decidir sobre as propostas de aplicação de equidade apresentadas pelos Conselhos de Contribuintes. (Vide Medida Provisória nº 449, de 2008)\nParágrafo único. O disposto no caput não se aplica aos casos de tratado, acordo internacional, lei ou ato normativo: (Incluído pela Medida Provisória nº 449, de 2008)\nI - que já tenha sido declarado inconstitucional por decisão plenária definitiva do Supremo Tribunal Federal; (Incluído pela Medida Provisória nº 449, de 2008)\nII - que fundamente crédito tributário objeto de: (Incluído pela Medida Provisória nº 449, de 2008)\na) dispensa legal de constituição ou de ato declaratório do Procurador-Geral da Fazenda Nacional, na forma dos arts. 18 e 19 da Lei no 10.522, de 19 de junho de 2002; (Incluído pela Medida Provisória nº 449, de 2008)\nb) súmula da Advocacia-Geral da União, na forma do art. 43 da Lei Complementar no 73, de 10 de fevereiro de 1993; ou (Incluído pela Medida Provisória nº 449, de 2008)\nc) pareceres do Advogado-Geral da União aprovados pelo Presidente da República, na forma do art. 40 da Lei Complementar no 73, de 1993. (Incluído pela Medida Provisória nº 449, de 2008)"},{"n":"26-A","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO V - Da Competência","t":"Art. 26-A. No âmbito do processo administrativo fiscal, fica vedado aos órgãos de julgamento afastar a aplicação ou deixar de observar tratado, acordo internacional, lei ou decreto, sob fundamento de inconstitucionalidade. (Redação dada pela Lei nº 11.941, de 2009)\n§ 1o (Revogado). (Redação dada pela Lei nº 11.941, de 2009)\n§ 2o (Revogado). (Redação dada pela Lei nº 11.941, de 2009)\n§ 3o (Revogado). (Redação dada pela Lei nº 11.941, de 2009)\n§ 4o (Revogado). (Redação dada pela Lei nº 11.941, de 2009)\n§ 5o (Revogado). (Redação dada pela Lei nº 11.941, de 2009)\n§ 6o O disposto no caput deste artigo não se aplica aos casos de tratado, acordo internacional, lei ou ato normativo: (Incluído pela Lei nº 11.941, de 2009)\nI – que já tenha sido declarado inconstitucional por decisão definitiva plenária do Supremo Tribunal Federal; (Incluído pela Lei nº 11.941, de 2009)\nII – que fundamente crédito tributário objeto de: (Incluído pela Lei nº 11.941, de 2009)\na) dispensa legal de constituição ou de ato declaratório do Procurador-Geral da Fazenda Nacional, na forma dos arts. 18 e 19 da Lei no 10.522, de 19 de julho de 2002; (Incluído pela Lei nº 11.941, de 2009)\nb) súmula da Advocacia-Geral da União, na forma do art. 43 da Lei Complementar no 73, de 10 de fevereiro de 1993; ou (Incluído pela Lei nº 11.941, de 2009)\nc) pareceres do Advogado-Geral da União aprovados pelo Presidente da República, na forma do art. 40 da Lei Complementar nº 73, de 10 de fevereiro de 1993. (Incluído pela Lei nº 11.941, de 2009)"},{"n":"27","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 27. Os processos remetidos para apreciação da autoridade julgadora de primeira instância deverão ser qualificados e identificados, tendo prioridade no julgamento aqueles em que estiverem presentes as circunstâncias de crime contra a ordem tributária ou de elevado valor, este definido em ato do Ministro de Estado da Fazenda. (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\n§ 1º Os processos serão julgados na ordem e nos prazos estabelecidos em ato do Secretário da Receita Federal, observada a prioridade de que trata o caput deste artigo. (Redação dada pela Lei Complementar nº 227, de 2026)\n§ 2º Relativamente ao processo relacionado em pauta de julgamento, é facultado ao sujeito passivo o pedido de retirada de pauta de sessão de julgamento agendada para o período referido no art. 5º-A deste Decreto, conforme disciplinado em ato do Secretário Especial da Receita Federal do Brasil. (Incluído pela Lei Complementar nº 227, de 2026)"},{"n":"28","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 28. Na decisão em que for julgada questão preliminar será também julgado o mérito, salvo quando incompatíveis, e dela constará o indeferimento fundamentado do pedido de diligência ou perícia, se for o caso. (Redação dada pela Lei nº 8.748, de 1993)"},{"n":"29","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 29. Na apreciação da prova, a autoridade julgadora formará livremente sua convicção, podendo determinar as diligências que entender necessárias."},{"n":"30","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 30. Os laudos ou pareceres do Laboratório Nacional de Análises, do Instituto Nacional de Tecnologia e de outros órgãos federais congêneres serão adotados nos aspectos técnicos de sua competência, salvo se comprovada a improcedência desses laudos ou pareceres.\n§ 1° Não se considera como aspecto técnico a classificação fiscal de produtos.\n§ 2º A existência no processo de laudos ou pareceres técnicos não impede a autoridade julgadora de solicitar outros a qualquer dos órgãos referidos neste artigo.\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n(Incluído pela Medida Provisória nº 1.602, de 1997)\n§ 3º Atribuir-se-á eficácia aos laudos e pareceres técnicos sobre produtos, exarados em outros processos administrativos fiscais e transladados mediante certidão de inteiro teor ou cópia fiel, nos seguintes casos: (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\na) quando tratarem de produtos originários do mesmo fabricante, com igual denominação, marca e especificação; (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\nb) quando tratarem de máquinas, aparelhos, equipamentos, veículos e outros produtos complexos de fabricação em série, do mesmo fabricante, com iguais especificações, marca e modelo. (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)"},{"n":"31","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 31. A decisão conterá relatório resumido do processo, fundamentos legais, conclusão e ordem de intimação, devendo referir-se, expressamente, a todos os autos de infração e notificações de lançamento objeto do processo, bem como às razões de defesa suscitadas pelo impugnante contra todas as exigências. (Redação dada pela Lei nº 8.748, de 1993)"},{"n":"32","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 32. As inexatidões materiais devidas a lapso manifesto e os erros de escrita ou de cálculos existentes na decisão poderão ser corrigidos de ofício ou a requerimento do sujeito passivo."},{"n":"33","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 33. Da decisão caberá recurso voluntário, total ou parcial, com efeito suspensivo, dentro dos 20 (vinte) dias úteis seguintes à ciência da decisão. (Redação dada pela Lei Complementar nº 227, de 2026)\n(Revogado pela Lei nº 12.096, de 2009)\n(Vide Adin nº 1.976-7)\n§ 3o O arrolamento de que trata o § 2o será realizado preferencialmente sobre bens imóveis. (Redação dada pela Lei nº 10.522, de 2002)\n§ 4o O Poder Executivo editará as normas regulamentares necessárias à operacionalização do arrolamento previsto no § 2o. (Redação dada pela Lei nº 10.522, de 2002)"},{"n":"34","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 34. A autoridade de primeira instância recorrerá de ofício sempre que a decisão:\n(Redação dada pela Lei nº 8.748, de 1993)\n(Redação dada pela Medida Provisória nº 1.602, de 1997)\nI - exonerar o sujeito passivo do pagamento de tributo e encargos de multa de valor total (lançamento principal e decorrentes) a ser fixado em ato do Ministro de Estado da Fazenda. (Redação dada pela Lei nº 9.532, de 1997) (Produção de efeito)\nII - deixar de aplicar pena de perda de mercadorias ou outros bens cominada à infração denunciada na formalização da exigência.\n§ 1º O recurso será interposto mediante declaração na própria decisão.\n§ 2° Não sendo interposto o recurso, o servidor que verificar o fato representará à autoridade julgadora, por intermédio de seu chefe imediato, no sentido de que seja observada aquela formalidade."},{"n":"35","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 35. O recurso, mesmo perempto, será encaminhado ao órgão de segunda instância, que julgará a perempção."},{"n":"36","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VI - Do Julgamento em Primeira Instância","t":"Art. 36. Da decisão de primeira instância não cabe pedido de reconsideração."},{"n":"37","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VII - Do Julgamento em Segunda Instância","t":"Art. 37. O julgamento no Conselho Administrativo de Recursos Fiscais far-se-á conforme dispuser o regimento interno. (Redação dada pela Lei nº 11.941, de 2009)\n. (Revogado pelo Decreto nº 83.304, de 1979)\nI - de decisão não-unânime de Câmara, turma de Câmara ou turma especial, quando for contrária à lei ou à evidência da prova; (Incluído pela Medida Provisória nº 449, de 2008)\nII - de decisão que der à lei tributária interpretação divergente da que lhe tenha dado outra Câmara, turma de Câmara, turma especial ou a própria Câmara Superior de Recursos Fiscais. (Incluído pela Medida Provisória nº 449, de 2008)\n§ 2o Caberá recurso especial à Câmara Superior de Recursos Fiscais, no prazo de 15 (quinze) dias da ciência do acórdão ao interessado: (Redação dada pela Lei nº 11.941, de 2009)\nI – (VETADO) (Redação dada pela Lei nº 11.941, de 2009)\nII – de decisão que der à lei tributária interpretação divergente da que lhe tenha dado outra Câmara, turma de Câmara, turma especial ou a própria Câmara Superior de Recursos Fiscais. (Redação dada pela Lei nº 11.941, de 2009)\n§ 3o No caso do inciso I do § 2o, o recurso é privativo do Procurador da Fazenda Nacional. (Redação dada pela Medida Provisória nº 449, de 2008)\n§ 3o Caberá pedido de reconsideração, com efeito suspensivo, no prazo de trinta dias, contados da ciência: (Vide Lei nº 11.941, de 2009)\nI – (revogado); (Redação dada pela Lei nº 11.941, de 2009)\nII – (revogado).(Redação dada pela Lei nº 11.941, de 2009)\n§ 4o Das decisões de Câmara, de turma de Câmara ou de turma especial que der provimento a recurso de ofício, caberá recurso voluntário, no prazo de trinta dias, à Câmara Superior de Recursos Fiscais. (Vide Medida Provisória nº 449, de 2008)\n§ 5º No caso do inciso II do § 2º deste artigo, em se tratando de contencioso relativo à Contribuição Social sobre Bens e Serviços, o recurso especial será cabível somente em relação à legislação específica da contribuição e o prazo para sua interposição será de 10 (dez) dias úteis da ciência do acórdão ao interessado. (Incluído pela Lei Complementar nº 227, de 2026)"},{"n":"38","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VII - Do Julgamento em Segunda Instância","t":"Art. 38. O julgamento em outros órgãos da administração federal far-se-á de acordo com a legislação própria, ou, na sua falta, conforme dispuser o órgão que administra o tributo."},{"n":"39","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VIII - Do Julgamento em Instância Especial","t":"Art. 39. Não cabe pedido de reconsideração de ato do Ministro da Fazenda que julgar ou decidir as matérias de sua competência."},{"n":"40","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VIII - Do Julgamento em Instância Especial","t":"Art. 40. As propostas de aplicação de equidade apresentadas pelos Conselhos de Contribuintes atenderão às características pessoais ou materiais da espécie julgada e serão restritas à dispensa total ou parcial de penalidade pecuniária, nos casos em que não houver reincidência nem sonegação, fraude ou conluio."},{"n":"41","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO VIII - Do Julgamento em Instância Especial","t":"Art. 41. O órgão preparador dará ciência ao sujeito passivo da decisão do Ministro da Fazenda, intimando-o, quando for o caso, a cumprí-la, no prazo de trinta dias."},{"n":"42","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO IX - Da Eficácia e Execução das Decisões","t":"Art. 42. São definitivas as decisões:\nI - de primeira instância esgotado o prazo para recurso voluntário sem que este tenha sido interposto;\nII - de segunda instância de que não caiba recurso ou, se cabível, quando decorrido o prazo sem sua interposição;\nIII - de instância especial.\nParágrafo único. Serão também definitivas as decisões de primeira instância na parte que não for objeto de recurso voluntário ou não estiver sujeita a recurso de ofício."},{"n":"43","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO IX - Da Eficácia e Execução das Decisões","t":"Art. 43. A decisão definitiva contrária ao sujeito passivo será cumprida no prazo para cobrança amigável fixado no artigo 21, aplicando-se, no caso de descumprimento, o disposto no § 3º do mesmo artigo.\n§ 1º A quantia depositada para evitar a correção monetária do crédito tributário ou para liberar mercadorias será convertida em renda se o sujeito passivo não comprovar, no prazo legal, a propositura de ação judicial.\n§ 2° Se o valor depositado não for suficiente para cobrir o crédito tributário, aplicar-se-á à cobrança do restante o disposto no caput deste artigo; se exceder o exigido, a autoridade promoverá a restituição da quantia excedente, na forma da legislação específica."},{"n":"44","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO IX - Da Eficácia e Execução das Decisões","t":"Art. 44. A decisão que declarar a perda de mercadoria ou outros bens será executada pelo órgão preparador, findo o prazo previsto no artigo 21, segundo dispuser a legislação aplicável."},{"n":"45","g":"","h":"CAPÍTULO I - Do Processo Fiscal › SEÇÃO IX - Da Eficácia e Execução das Decisões","t":"Art. 45. No caso de decisão definitiva favorável ao sujeito passivo, cumpre à autoridade preparadora exonerá-lo, de ofício, dos gravames decorrentes do litígio."},{"n":"46","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 46. O sujeito passivo poderá formular consulta sobre dispositivos da legislação tributária aplicáveis a fato determinado. (Vide Lei nº 9.430, de 1996)\nParágrafo único. Os órgãos da administração pública e as entidades representativas de categorias econômicas ou profissionais também poderão formular consulta."},{"n":"47","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 47. A consulta deverá ser apresentada por escrito, no domicílio tributário do consulente, ao órgão local da entidade incumbida de administrar o tributo sobre que versa. (Vide Lei nº 9.430, de 1996)"},{"n":"48","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 48. Salvo o disposto no artigo seguinte, nenhum procedimento fiscal será instaurado contra o sujeito passivo relativamente à espécie consultada, a partir da apresentação da consulta até o trigésimo dia subseqüente à data da ciência: (Vide Lei nº 9.430, de 1996)\nI - de decisão de primeira instância da qual não haja sido interposto recurso;\nII - de decisão de segunda instância."},{"n":"49","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 49. A consulta não suspende o prazo para recolhimento de tributo, retido na fonte ou autolançado antes ou depois de sua apresentação, nem o prazo para apresentação de declaração de rendimentos. (Vide Lei nº 9.430, de 1996)"},{"n":"50","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 50. A decisão de segunda instância não obriga ao recolhimento de tributo que deixou de ser retido ou autolançado após a decisão reformada e de acordo com a orientação desta, no período compreendido entre as datas de ciência das duas decisões. (Vide Lei nº 9.430, de 1996)"},{"n":"51","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 51. No caso de consulta formulada por entidade representativa de categoria econômica ou profissional, os efeitos referidos no artigo 48 só alcançam seus associados ou filiados depois de cientificado o consulente da decisão. (Vide Lei nº 9.430, de 1996)"},{"n":"52","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 52. Não produzirá efeito a consulta formulada: (Vide Lei nº 9.430, de 1996)\nI - em desacordo com os artigos 46 e 47;\nII - por quem tiver sido intimado a cumprir obrigação relativa ao fato objeto da consulta;\nIII - por quem estiver sob procedimento fiscal iniciado para apurar fatos que se relacionem com a matéria consultada;\nIV - quando o fato já houver sido objeto de decisão anterior, ainda não modificada, proferida em consulta ou litígio em que tenha sido parte o consulente;\nV - quando o fato estiver disciplinado em ato normativo, publicado antes de sua apresentação;\nVI - quando o fato estiver definido ou declarado em disposição literal de lei;\nVII - quando o fato for definido como crime ou contravenção penal;\nVIII - quando não descrever, completa ou exatamente, a hipótese a que se referir, ou não contiver os elementos necessários à sua solução salvo se a inexatidão ou omissão for escusável, a critério da autoridade julgadora."},{"n":"53","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 53. O preparo do processo compete ao órgão local da entidade encarregada da administração do tributo. (Vide Lei nº 9.430, de 1996)"},{"n":"54","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 54. O julgamento compete: (Vide Lei nº 9.430, de 1996)\nI - Em primeira instância:\na) aos Superintendentes Regionais da Receita Federal, quanto aos tributos administrados pela Secretaria da Receita Federal, atendida, no julgamento, a orientação emanada dos atos normativos da Coordenação do Sistema de Tributação;\nb) às autoridades referidas na alínea b do inciso I do artigo 25.\nII - Em segunda instância:\na) ao Coordenador do Sistema de Tributação, da Secretaria da Receita Federal, salvo quanto aos tributos incluídos na competência julgadora de outro órgão da administração federal;\nb) à autoridade mencionada na legislação dos tributos, ressalvados na alínea precedente ou, na falta dessa indicação, à que for designada pela entidade que administra o tributo.\nIII - Em instância única, ao Coordenador do Sistema de Tributação, quanto às consultas relativas aos tributos administrados pela Secretaria da Receita Federal e formuladas:\na) sobre classificação fiscal de mercadorias;\nb) pelos órgãos centrais da administração pública;\nc) por entidades representativas de categorias econômicas ou profissionais, de âmbito nacional."},{"n":"55","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 55. Compete à autoridade julgadora declarar a ineficácia da Consulta. (Vide Lei nº 9.430, de 1996)"},{"n":"56","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 56. Cabe recurso voluntário, com efeito suspensivo, de decisão de primeira instância, dentro de trinta dias contados da ciência. (Vide Lei nº 9.430, de 1996)"},{"n":"57","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 57. A autoridade de primeira instância recorrerá de ofício de decisão favorável ao consulente. (Vide Lei nº 9.430, de 1996)"},{"n":"58","g":"","h":"CAPÍTULO II - Do Processo da Consulta","t":"Art. 58. Não cabe pedido de reconsideração de decisão proferida em processo de consulta, inclusive da que declarar a sua ineficácia. (Vide Lei nº 9.430, de 1996)"},{"n":"59","g":"","h":"CAPÍTULO III - Das Nulidades","t":"Art. 59. São nulos:\nI - os atos e termos lavrados por pessoa incompetente;\nII - os despachos e decisões proferidos por autoridade incompetente ou com preterição do direito de defesa.\n§ 1º A nulidade de qualquer ato só prejudica os posteriores que dele diretamente dependam ou sejam conseqüência.\n§ 2º Na declaração de nulidade, a autoridade dirá os atos alcançados, e determinará as providências necessárias ao prosseguimento ou solução do processo.\n§ 3º Quando puder decidir do mérito a favor do sujeito passivo a quem aproveitaria a declaração de nulidade, a autoridade julgadora não a pronunciará nem mandará repetir o ato ou suprir-lhe a falta. (Redação dada pela Lei nº 8.748, de 1993)"},{"n":"60","g":"","h":"CAPÍTULO III - Das Nulidades","t":"Art. 60. As irregularidades, incorreções e omissões diferentes das referidas no artigo anterior não importarão em nulidade e serão sanadas quando resultarem em prejuízo para o sujeito passivo, salvo se este lhes houver dado causa, ou quando não influírem na solução do litígio."},{"n":"61","g":"","h":"CAPÍTULO III - Das Nulidades","t":"Art. 61. A nulidade será declarada pela autoridade competente para praticar o ato ou julgar a sua legitimidade."},{"n":"62","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 62. Durante a vigência de medida judicial que determinar a suspensão da cobrança, do tributo não será instaurado procedimento fiscal contra o sujeito passivo favorecido pela decisão, relativamente, à matéria sobre que versar a ordem de suspensão.\nParágrafo único. Se a medida referir-se a matéria objeto de processo fiscal, o curso deste não será suspenso, exceto quanto aos atos executórios."},{"n":"63","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 63. A destinação de mercadorias ou outros bens apreendidos ou dados em garantia de pagamento do crédito tributário obedecerá às normas estabelecidas na legislação aplicável."},{"n":"64","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 64. Os documentos que instruem o processo poderão ser restituídos, em qualquer fase, a requerimento do sujeito passivo, desde que a medida não prejudique a instrução e deles fique cópia autenticada no processo."},{"n":"64-A","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 64-A. Os documentos que instruem o processo poderão ser objeto de digitalização, observado o disposto nos arts. 1o e 3º da Lei nº 12.682, de 9 de julho de 2012. (Incluído pela Lei nº 12.865, de 2013)"},{"n":"64-B","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 64-B. No processo eletrônico, os atos, documentos e termos que o instruem poderão ser natos digitais ou produzidos por meio de digitalização, observado o disposto na Medida Provisória no 2.200-2, de 24 de agosto de 2001. (Incluído pela Lei nº 12.865, de 2013)\n§ 1o Os atos, termos e documentos submetidos a digitalização pela administração tributária e armazenados eletronicamente possuem o mesmo valor probante de seus originais. (Incluído pela Lei nº 12.865, de 2013)\n§ 2o Os autos de processos eletrônicos, ou parte deles, que tiverem de ser remetidos a órgãos ou entidades que não disponham de sistema compatível de armazenagem e tramitação poderão ser encaminhados impressos em papel ou por meio digital, conforme disciplinado em ato da administração tributária. (Incluído pela Lei nº 12.865, de 2013)\n§ 3o As matrizes físicas dos atos, dos termos e dos documentos digitalizados e armazenados eletronicamente, nos termos do § 1o, poderão ser descartadas, conforme regulamento. (Incluído pela Lei nº 13.097, de 2015)"},{"n":"65","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 65. O disposto neste Decreto não prejudicará a validade dos atos praticados na vigência da legislação anterior.\n§ 1° O preparo dos processos em curso, até a decisão de primeira instância, continuará regido pela legislação precedente.\n§ 2º Não se modificarão os prazos iniciados antes da entrada em vigor deste Decreto."},{"n":"66","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 66. O Conselho Superior de Tarifa passa a denominar-se 4º Conselho de Contribuintes."},{"n":"67","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 67. Os Conselhos de Contribuintes, no prazo de noventa dias, adaptarão seus regimentos internos às disposições deste Decreto."},{"n":"68","g":"","h":"CAPÍTULO IV - Disposições Finais e Transitórias","t":"Art. 68. Revogam-se as disposições em contrário.\nBrasília, 6 de março de 1972; 151º da Independência e 84º da República.\nEMÍLIO G. MÉDICI\nAntônio Delfim Netto\nEste texto não substitui o publicado no DOU de 7.3.1972\n*"}] };
